import XCTest
import AppKit
import DiskUI

/// Verifies the packaged mark, the artwork every in-app icon is drawn from.
///
/// The image is generated by `Scripts/make-icon.swift` rather than shipped by
/// hand, so these check that the resource actually reaches the UI bundle, decodes
/// at the icon's resolution, and carries the circular body rather than the
/// macOS icon's rounded square.
final class AppMarkQATests: XCTestCase {

    @MainActor
    func testMarkIsPackagedAtIconResolution() {
        let image = AppMarkImage.shared
        let rep = image.representations.compactMap { $0 as? NSBitmapImageRep }.first

        XCTAssertEqual(rep?.pixelsWide, 1024)
        XCTAssertEqual(rep?.pixelsHigh, 1024)
    }

    @MainActor
    func testMarkIsTheCircleNotTheMacOSBody() throws {
        let rep = try XCTUnwrap(
            AppMarkImage.shared.representations.compactMap { $0 as? NSBitmapImageRep }.first,
            "the mark must decode as a bitmap"
        )

        // The mark's own body is a circle: the corners outside it are clear, so
        // the in-app icon never shows the rounded-square ground the macOS icon
        // uses. Sample a few pixels in from each corner, inside the opaque centre,
        // and just inside the top edge.
        let corners = [(2, 2), (rep.pixelsWide - 3, 2), (2, rep.pixelsHigh - 3),
                       (rep.pixelsWide - 3, rep.pixelsHigh - 3)]
        for (x, y) in corners {
            let alpha = rep.colorAt(x: x, y: y)?.alphaComponent ?? 1
            XCTAssertEqual(alpha, 0, accuracy: 0.01,
                           "corner (\(x), \(y)) must be outside the circular body")
        }

        XCTAssertEqual(rep.colorAt(x: rep.pixelsWide / 2, y: rep.pixelsHigh / 2)?.alphaComponent ?? 0,
                       1, "the spindle at the centre must be opaque")
        XCTAssertEqual(rep.colorAt(x: rep.pixelsWide / 2, y: 8)?.alphaComponent ?? 0,
                       1, "the top of the disc must be inside the circular body")
    }
}
